func contactStoredInLabels(ctx context.Context, profile *models.ContactProfile, accounts []models.Account) []string {
	labels := []string{}
	if profile == nil {
		return labels
	}
	seen := map[string]bool{}
	home := strings.TrimSpace(profile.Home)
	if home == "" {
		home = "local"
	}
	var places []string
	for _, card := range profile.Cards {
		if card.IsDeleted {
			continue
		}
		switch {
		case card.Kind == "local":
			places = append(places, "local")
		case card.Kind == "provider":
			place := "account:" + card.AccountID
			if card.AddressBookID != "" {
				place = "book:" + card.AddressBookID
			}
			places = append(places, place)
		}
	}
	accountOf := func(place string) string {
		for _, card := range profile.Cards {
			if card.Kind == "provider" && (place == "account:"+card.AccountID || place == "book:"+card.AddressBookID) {
				return card.AccountID
			}
		}
		if account, ok := strings.CutPrefix(place, "account:"); ok {
			return account
		}
		if book, ok := strings.CutPrefix(place, "book:"); ok {
			for _, account := range accounts {
				for _, candidate := range account.ContactAddressBooks {
					if candidate.ID == book {
						return account.ID
					}
				}
			}
		}
		return ""
	}
	label := func(place string) string {
		if place == "local" {
			return i18n.T(ctx, "contacts.origin.local")
		}
		return contactStoredInPlaceLabel(ctx, place, accountOf(place), accounts)
	}
	if home != "" {
		text := label(home)
		if !slices.Contains(places, home) {
			text = i18n.T(ctx, "contacts.stored_in_writing", "place", text)
		}
		labels = appendUniqueContactReadLabel(labels, seen, text)
	}
	return labels
}

